        "code": "let totalBytes = 0;\n\nrecorder.ondataavailable = (e) => {\n  if (e.data.size === 0) return;\n  chunks.push(e.data);\n  totalBytes += e.data.size;\n  console.log(`📊 Total:${(totalBytes / 1024).toFixed(1)} KB`);\n};",
